require_once dirname(__DIR__).'/includes/auth.php';$u=require_role('coordinator');$err='';$ownDept=(int)($u['department_id']??0);if(!$ownDept){http_response_code(403);exit('This HOD account has no department assignment. Contact the administrator.');}
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=(string)($_POST['action']??'');
 if($action==='create_supervisor'){
  $first=post_string('first_name',80);$last=post_string('last_name',80);$email=strtolower(post_string('email',190));$staff=strtoupper(post_string('staff_number',40));
  if(!$first||!$last||!$staff||!filter_var($email,FILTER_VALIDATE_EMAIL))$err='Enter the supervisor name, staff number, and a valid email.';
  else{$q=db()->prepare('SELECT id FROM users WHERE email=? OR staff_number=?');$q->execute([$email,$staff]);if($q->fetchColumn())$err='That email or staff number is already registered.';else try{$q=db()->prepare("INSERT INTO users(role_id,department_id,staff_number,first_name,last_name,email,password_hash,profile_complete,must_change_password) VALUES((SELECT id FROM roles WHERE name='supervisor'),?,?,?,?,?,?,0,1)");$q->execute([$ownDept,$staff,$first,$last,$email,password_hash('password',PASSWORD_DEFAULT)]);$id=(int)db()->lastInsertId();audit('supervisor_profile_created','user',$id,'HOD created supervisor profile in department '.$ownDept);notify_user($id,'Complete your supervisor profile','Your HOD created your supervisor account. Sign in with your staff number and the temporary password, then change your password and finish your profile.','action','user',$id);flash('success','Supervisor profile created. Give the supervisor the shared temporary password: password. They must change it and complete their profile at first sign-in.');redirect('coordinator/students.php');}catch(PDOException $e){$err='The supervisor profile could not be created. Check for duplicate email or staff number.';}}
 }elseif($action==='register_batch'){
  $raw=post_string('matric_list',20000);$defaultProgramme=(int)($_POST['default_programme_id']??0);$supervisor=(int)($_POST['supervisor_id']??0);$lines=preg_split('/\R/u',$raw,-1,PREG_SPLIT_NO_EMPTY);$entries=[];$seen=[];$problems=[];
  if(!$lines)$problems[]='Enter at least one matric number.';
  $programQuery=db()->prepare('SELECT id,code,name FROM programmes WHERE id=? AND department_id=? AND is_active=1');
  $byCode=db()->prepare('SELECT id,code,name FROM programmes WHERE UPPER(code)=UPPER(?) AND department_id=? AND is_active=1');
  $existing=db()->prepare("SELECT u.id FROM users u JOIN roles r ON r.id=u.role_id WHERE UPPER(u.matric_number)=UPPER(?) AND r.name='student'");
  foreach($lines as $index=>$line){$parts=preg_split('/[|\t]/u',trim($line));$matric=strtoupper(trim($parts[0]??''));$programCode=trim($parts[1]??'');if(count($parts)>2||!$matric||mb_strlen($matric)>40){$problems[]='Line '.($index+1).': invalid matric number format.';continue;}if(isset($seen[$matric])){$problems[]='Line '.($index+1).': repeated matric number '.$matric.'.';continue;}$seen[$matric]=true;$existing->execute([$matric]);if($existing->fetchColumn()){$problems[]='Line '.($index+1).': matric number '.$matric.' is already registered.';continue;}
   if($programCode){$byCode->execute([$programCode,$ownDept]);$programme=$byCode->fetch();}else{$programQuery->execute([$defaultProgramme,$ownDept]);$programme=$programQuery->fetch();}
   if(!$programme){$problems[]='Line '.($index+1).': choose a valid programme in your department or add its programme code after a vertical bar.';continue;}$entries[]=['matric'=>$matric,'programme_id'=>(int)$programme['id']];
  }
  if($supervisor){$q=db()->prepare("SELECT id FROM users WHERE id=? AND role_id=(SELECT id FROM roles WHERE name='supervisor') AND account_status='active' AND department_id=?");$q->execute([$supervisor,$ownDept]);if(!$q->fetchColumn())$problems[]='The selected supervisor must be active and in your department.';}
  if($problems)$err=implode(' ',$problems);
  else try{db()->beginTransaction();$insert=db()->prepare("INSERT INTO users(role_id,department_id,programme_id,matric_number,first_name,last_name,email,password_hash,profile_complete,must_change_password) VALUES((SELECT id FROM roles WHERE name='student'),?,?,?,NULL,NULL,NULL,?,0,1)");$assign=$supervisor?db()->prepare('INSERT INTO student_supervisors(student_id,supervisor_id,assigned_by) VALUES(?,?,?)'):null;foreach($entries as $entry){$insert->execute([$ownDept,$entry['programme_id'],$entry['matric'],password_hash('password',PASSWORD_DEFAULT)]);$studentId=(int)db()->lastInsertId();if($assign)$assign->execute([$studentId,$supervisor,$u['id']]);audit('student_registered','user',$studentId,'HOD registered matric '.$entry['matric']);}db()->commit();if($supervisor){notify_user($supervisor,count($entries).' students assigned','Your HOD assigned '.count($entries).' student(s) to you.','action','user',$supervisor);}flash('success',count($entries).' student account(s) created with the shared temporary password: password. Each student must change it and complete their profile before proceeding.');redirect('coordinator/students.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());$err='The student batch could not be registered. No accounts were saved; check matric numbers and retry.';}
 }elseif($action==='assign'){
  $student=(int)($_POST['student_id']??0);$supervisor=(int)($_POST['supervisor_id']??0);$q=db()->prepare("SELECT id FROM users WHERE id=? AND role_id=(SELECT id FROM roles WHERE name='student') AND department_id=?");$q->execute([$student,$ownDept]);$validStudent=(bool)$q->fetchColumn();$q=db()->prepare("SELECT id FROM users WHERE id=? AND role_id=(SELECT id FROM roles WHERE name='supervisor') AND account_status='active' AND department_id=?");$q->execute([$supervisor,$ownDept]);
  if(!$validStudent||!$q->fetchColumn())$err='Choose a student and active supervisor from your department.';else{try{db()->beginTransaction();db()->prepare('UPDATE student_supervisors SET ended_at=NOW() WHERE student_id=? AND ended_at IS NULL')->execute([$student]);db()->prepare('INSERT INTO student_supervisors(student_id,supervisor_id,assigned_by) VALUES(?,?,?)')->execute([$student,$supervisor,$u['id']]);$projectQ=db()->prepare('SELECT p.id,p.status FROM projects p JOIN project_members pm ON pm.project_id=p.id WHERE pm.student_id=? ORDER BY p.created_at DESC LIMIT 1');$projectQ->execute([$student]);$existingProject=$projectQ->fetch();$projectId=(int)($existingProject['id']??0);if($projectId){db()->prepare('UPDATE project_supervisors SET ended_at=NOW() WHERE project_id=? AND ended_at IS NULL')->execute([$projectId]);db()->prepare('INSERT INTO project_supervisors(project_id,supervisor_id,assigned_by) VALUES(?,?,?)')->execute([$projectId,$supervisor,$u['id']]);$approved=db()->prepare("SELECT COUNT(*) FROM project_ideas WHERE project_id=? AND review_status='approved'");$approved->execute([$projectId]);$started=in_array($existingProject['status'],['proposal_submitted','in_progress','correction_required','final_submission','under_evaluation','approved','completed','archived'],true);$nextStatus=$started?$existingProject['status']:((int)$approved->fetchColumn()>0?'supervisor_assigned':'idea_under_review');db()->prepare('UPDATE projects SET status=? WHERE id=?')->execute([$nextStatus,$projectId]);}db()->commit();notify_user($student,'Supervisor assigned','Your HOD assigned a project supervisor.','success','user',$student);notify_user($supervisor,'Student assigned','Your HOD assigned a student to you.','action','user',$student);if($projectId)notify_user($supervisor,'Project supervision assigned','The student has a registered project and project ideas awaiting review.','action','project',$projectId);audit('student_supervisor_assigned','user',$student,'HOD assigned supervisor '.$supervisor);flash('success','Supervisor assignment saved. The supervisor can now see the student and any registered project.');redirect('coordinator/students.php');}catch(Throwable $e){if(db()->inTransaction())db()->rollBack();error_log($e->getMessage());$err='The supervisor assignment could not be saved.';}}
 }
}
$q=db()->prepare('SELECT p.id,p.code,p.name programme FROM programmes p WHERE p.department_id=? AND p.is_active=1 ORDER BY p.name');$q->execute([$ownDept]);$programmes=$q->fetchAll();$q=db()->prepare("SELECT id,first_name,last_name,staff_number FROM users WHERE role_id=(SELECT id FROM roles WHERE name='supervisor') AND account_status='active' AND department_id=? ORDER BY last_name,first_name");$q->execute([$ownDept]);$supervisors=$q->fetchAll();
$q=db()->prepare("SELECT u.id,u.matric_number,u.first_name,u.last_name,u.profile_complete,f.name faculty,d.name department,p.name programme,su.id supervisor_id,su.first_name supervisor_first,su.last_name supervisor_last FROM users u JOIN roles r ON r.id=u.role_id JOIN departments d ON d.id=u.department_id JOIN faculties f ON f.id=d.faculty_id LEFT JOIN programmes p ON p.id=u.programme_id LEFT JOIN student_supervisors ss ON ss.student_id=u.id AND ss.ended_at IS NULL LEFT JOIN users su ON su.id=ss.supervisor_id WHERE r.name='student' AND d.id=? ORDER BY u.created_at DESC");$q->execute([$ownDept]);$students=$q->fetchAll();$q=db()->prepare('SELECT d.name department,f.name faculty FROM departments d JOIN faculties f ON f.id=d.faculty_id WHERE d.id=?');$q->execute([$ownDept]);$department=$q->fetch();$pageTitle='Student Progress Registry';$crumbTrail=['Students'];require dirname(__DIR__).'/includes/header.php';
?>
<?php if($err): ?><div role="alert" class="alert alert-danger"><?= e($err) ?></div><?php endif; ?>
<?php $nDone=count(array_filter($students,fn($x)=>!empty($x['profile_complete'])));$nAssigned=count(array_filter($students,fn($x)=>!empty($x['supervisor_id']))); ?>
<div class="row g-3 mb-3"><div class="col-md-4"><div class="stat-card"><div class="stat-label">Students</div><div class="stat-value"><?= count($students) ?></div><small class="stat-sub"><?= e($department['department']) ?> · <?= e($department['faculty']) ?></small></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Profiles complete</div><div class="stat-value text-green"><?= (int)$nDone ?></div><small class="stat-sub">Students who finished sign-up</small></div></div><div class="col-md-4"><div class="stat-card"><div class="stat-label">Supervisor assigned</div><div class="stat-value text-blue"><?= (int)$nAssigned ?></div><small class="stat-sub"><?= (int)(count($students)-$nAssigned) ?> still pending</small></div></div></div>
<section class="card filter-bar mb-3"><div class="filter-form"><label class="search-box"><?= ui_icon('search') ?><input class="form-control" id="departmentStudentSearch" type="search" placeholder="Search by name, matric number, programme or supervisor" aria-label="Search students" data-live-filter="#departmentStudents tbody tr"></label><span class="filter-note"><?= e($department['department']) ?></span></div></section>
<section class="card p-4 mb-3"><div class="section-row mb-3"><h2 class="section-heading mb-0">Coordinated Student Registry</h2><span class="text-muted small"><?= count($students) ?> students</span></div><div class="table-responsive"><table class="table table-soft align-middle" id="departmentStudents"><thead><tr><th>Student</th><th>Faculty / department / programme</th><th>Profile</th><th>Supervisor</th><th>Assign or reassign</th></tr></thead><tbody>
<?php foreach($students as $s): $nm=trim(($s['first_name']??'').' '.($s['last_name']??'')); ?><tr><td><div class="person"><span class="person-avatar"><?= e(ui_initials($nm?:'S')) ?></span><div><strong><?= e($nm?:'Profile not completed') ?></strong><small><?= e($s['matric_number']) ?></small></div></div></td><td><?= e($s['faculty']) ?><br><small class="text-muted"><?= e($s['department']) ?> · <?= e($s['programme']??'Programme not set') ?></small></td><td><?= !empty($s['profile_complete'])?'<span class="ui-pill is-ok">Complete</span>':'<span class="ui-pill is-warn">Awaiting student</span>' ?></td><td><?= e(trim(($s['supervisor_first']??'').' '.($s['supervisor_last']??''))?:'Pending') ?></td><td><?php if($supervisors): ?><form method="post" class="d-flex gap-2"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="assign"><input type="hidden" name="student_id" value="<?= (int)$s['id'] ?>"><select class="form-select form-select-sm" name="supervisor_id" required><option value="">Select</option><?php foreach($supervisors as $sp): ?><option value="<?= (int)$sp['id'] ?>" <?= (int)$s['supervisor_id']===(int)$sp['id']?'selected':'' ?>><?= e(trim(($sp['first_name']??'').' '.($sp['last_name']??''))) ?></option><?php endforeach; ?></select><button class="btn btn-sm btn-outline-primary">Save</button></form><?php else: ?><small class="text-muted">Create a supervisor profile first</small><?php endif; ?></td></tr><?php endforeach; ?>
<?php if(!$students): ?><tr><td colspan="5"><div class="empty-state">No students have been registered in this department yet.</div></td></tr><?php endif; ?></tbody></table></div></section>
<details class="card record-card mb-3"><summary><span class="section-heading mb-0">Register student matric numbers</span><span class="chev"><?= ui_icon('chevron',16) ?></span></summary><div class="p-4 pt-2"><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="register_batch"><label class="form-label" for="matric_list">One student per line</label><textarea class="form-control mb-2" id="matric_list" name="matric_list" rows="7" placeholder="NAUB/2022/001&#10;NAUB/2022/002 | BSC-IS" required></textarea><div class="form-text mb-3">Choose a default programme below, or include a programme code after | on any line for mixed-programme batches.</div><div class="row g-2"><div class="col-md-6"><label class="form-label">Default programme</label><select class="form-select" name="default_programme_id"><option value="0">Use line-specific codes only</option><?php foreach($programmes as $p): ?><option value="<?= (int)$p['id'] ?>"><?= e($p['programme'].' · '.$p['code']) ?></option><?php endforeach; ?></select></div><div class="col-md-6"><label class="form-label">Assign supervisor to this batch (optional)</label><select class="form-select" name="supervisor_id"><option value="0">Assign later</option><?php foreach($supervisors as $s): ?><option value="<?= (int)$s['id'] ?>"><?= e(trim(($s['first_name']??'').' '.($s['last_name']??'')).' · '.$s['staff_number']) ?></option><?php endforeach; ?></select></div></div><button class="btn btn-primary mt-3">Create student accounts</button></form></div></details>
